CREATE TYPE "Role" AS ENUM ('CUSTOMER', 'ADMIN');
CREATE TYPE "EnquiryType" AS ENUM ('CART', 'PRODUCT', 'CONTACT');
CREATE TYPE "EnquiryStatus" AS ENUM ('NEW', 'CONTACTED', 'CLOSED');
CREATE TYPE "BannerDisplayMode" AS ENUM ('TEXT_ONLY', 'IMAGE_ONLY', 'TEXT_OVER_IMAGE');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'CUSTOMER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "material" TEXT NOT NULL, "price" DOUBLE PRECISION NOT NULL, "image" TEXT NOT NULL, "description" TEXT NOT NULL, "featured" BOOLEAN NOT NULL DEFAULT false, "isNew" BOOLEAN NOT NULL DEFAULT false, "metaTitle" TEXT, "metaDescription" TEXT, "ogImageUrl" TEXT, "keywords" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "canonicalUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Enquiry" ("id" TEXT PRIMARY KEY, "type" "EnquiryType" NOT NULL, "customerName" TEXT NOT NULL, "customerEmail" TEXT, "customerPhone" TEXT, "productIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "message" TEXT, "currency" TEXT NOT NULL, "region" TEXT, "status" "EnquiryStatus" NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Banner" ("id" TEXT PRIMARY KEY, "sectionKey" TEXT NOT NULL UNIQUE, "displayMode" "BannerDisplayMode" NOT NULL, "eyebrow" TEXT, "headline" TEXT, "subheadline" TEXT, "bodyText" TEXT, "imageUrl" TEXT, "order" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
